protected void init()
{
    api = XAPI_APIS::GetCost;
    super();
}

protected str body()
{
    Map configMap = new Map(Types::String, Types::String);

    configMap.insert('<DataAreaId>',    curExt());
    configMap.insert('<custAccount>',    XAPI_APILogTable::getValueByKey(XAPI_APIS::CreateCustomer, 'CustAccount'));
    configMap.insert('<costId>',        XAPI_APILogTable::getValueByKey(XAPI_APIS::GetLocations, 'DelPointRecId'));

    return this.prepareBody(configMap);
}
